  try {
    size = statSync(path).size;
  } catch {
    throw new Error(`could not read ${path}: no such file`);
  }
  if (mode === "upload" && size > UPLOAD_LIMIT_BYTES) {
    throw new Error(
      `${path} is ${size} bytes, over the ${UPLOAD_LIMIT_BYTES}-byte attachment ceiling. ` +
