      mode,
      sent: url,
      content_length: body ? body.length : 0,
      credential: `present, prefix ${kind}`,
      status: response.status,
      location: location ?? null,
      body_excerpt: responseText.slice(0, BODY_EXCERPT_CHARS) || null,
      interpretation,
    },
    null,
    2,
  );
}

